<script setup>
import { onMounted, ref } from 'vue';
import LoadingBlock from '../components/LoadingBlock.vue'; import PageHeading from '../components/PageHeading.vue'; import { api, apiMessage } from '../lib/api';
const year=ref(String(new Date().getFullYear())),period=ref('q1'),data=ref(null),loading=ref(false),error=ref('');const percent=(v)=>v==null?'—':`${(Number(v)*100).toFixed(1)}%`;const amount=(v)=>Number(v??0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});
const load=async()=>{loading.value=true;error.value='';try{data.value=(await api.get('/workplan-performance/state/executive',{params:{year:year.value,period:period.value}})).data.data}catch(e){error.value=apiMessage(e)}finally{loading.value=false}};onMounted(load);
</script>
<template><div class="executive-print"><header class="executive-print-header"><strong>HMB-eHRMIS</strong><span>State Executive Performance Report</span><span v-if="data">{{data.year}} · {{data.period.toUpperCase()}} · Generated {{data.generated_at}}</span></header><PageHeading eyebrow="Performance management" title="State Executive Performance"><button class="civic-button civic-button-primary no-print" :disabled="loading" @click="window.print()">Print Executive View</button></PageHeading><div v-if="error" class="civic-error no-print">{{error}}</div><section class="civic-workspace no-print"><div class="civic-form-grid"><label class="civic-field"><span>Year</span><input v-model="year" type="number"></label><label class="civic-field"><span>Period</span><select v-model="period"><option v-for="value in ['q1','q2','q3','q4','annual']" :key="value" :value="value">{{value.toUpperCase()}}</option></select></label><div class="civic-field"><span>&nbsp;</span><button class="civic-button civic-button-primary" :disabled="loading" @click="load">Apply</button></div></div></section><LoadingBlock v-if="loading"/><template v-else-if="data"><section class="civic-workspace"><h3>State summary — {{data.period.toUpperCase()}} {{data.year}}</h3><div class="civic-form-grid"><p class="civic-field"><span>Official achievement</span><strong>{{percent(data.state.official_score)}}</strong></p><p class="civic-field"><span>Reporting completeness</span><strong>{{percent(data.state.reporting_completeness.ratio)}}</strong></p><p class="civic-field"><span>Evidence coverage</span><strong>{{percent(data.state.evidence_coverage.ratio)}}</strong></p><p class="civic-field"><span>Financial execution</span><strong>{{percent(data.state.financial_execution.ratio)}}</strong></p><p class="civic-field"><span>Expected / verified / missing reports</span><strong>{{data.state.reporting_completeness.expected_reports}} / {{data.state.reporting_completeness.verified_reports}} / {{data.state.reporting_completeness.missing_or_unverified_reports}}</strong></p><p class="civic-field"><span>MDA classifications</span><strong>{{data.classifications.ranked_count}} ranked · {{data.classifications.insufficient_reporting_count}} insufficient · {{data.classifications.no_eligible_plan_data_count}} no plan</strong></p></div></section><section class="civic-workspace"><h3>State MDA performance</h3><div class="civic-table-wrap"><table class="civic-table"><thead><tr><th>Rank</th><th>MDA</th><th>Revision</th><th>Achievement</th><th>Completeness</th><th>Evidence</th><th>Financial execution</th><th>Missing reports</th><th>Status</th></tr></thead><tbody><tr v-for="mda in data.mdas" :key="mda.id"><td>{{mda.rank??'—'}}</td><td><RouterLink :to="{path:'/workplan-performance',query:{workplan_id:mda.workplan_id,period:data.period}}">{{mda.name}}</RouterLink></td><td>Revision {{mda.revision_no}}</td><td>{{percent(mda.official_score)}}</td><td>{{percent(mda.reporting_completeness.ratio)}}</td><td>{{percent(mda.evidence_coverage.ratio)}}</td><td>{{percent(mda.financial_execution.ratio)}}</td><td>{{mda.reporting_completeness.missing_or_unverified_reports}}</td><td>{{mda.rank_status.replaceAll('_',' ')}}</td></tr></tbody></table></div></section><section class="civic-workspace"><h3>Executive trend observations</h3><div class="civic-table-wrap"><table class="civic-table"><thead><tr><th>MDA</th><th v-for="item in data.trends.periods" :key="item">{{item.toUpperCase()}}</th></tr></thead><tbody><tr v-for="mda in data.trends.mdas" :key="mda.id"><td>{{mda.name}}</td><td v-for="item in data.trends.periods" :key="item"><RouterLink v-if="mda.observations[item]?.workplan_id" :to="{path:'/workplan-performance',query:{workplan_id:mda.observations[item].workplan_id,period:item}}">{{percent(mda.observations[item].official_score)}}</RouterLink><template v-else>—</template><br><small v-if="mda.observations[item]">Rev {{mda.observations[item].revision_no??'—'}}</small></td></tr></tbody></table></div></section><section class="civic-workspace executive-methodology"><h3>Methodology and reporting disclaimer</h3><p>Official achievement is calculated from verified progress reports against the approved Workplan structure. Missing or unverified expected reports contribute zero achievement. MDA ranking requires the configured minimum reporting-completeness threshold.</p><p>Reporting completeness is presented separately from achievement. MDAs below the approved reporting-completeness threshold remain visible but are not assigned a numerical rank.</p><p>Evidence coverage and financial execution are informational metrics and do not contribute to the achievement score or rank.</p><p class="print-only">Print-friendly Executive View — not a certified report or formal export.</p></section></template></div></template>
